import pyomo.environ as pyo

DATA = {
    "sources": ["coal", "gas", "nuclear"],
    "cost": {"coal": 4, "gas": 3, "nuclear": 2},
    "capacity": {"coal": 3000, "gas": 2000, "nuclear": 1500},
    "demand": 5000,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.S = pyo.Set(initialize=d["sources"])

    # Variables: whole numbers of units, one per source, bounded by capacity
    def x_bounds(m, s):
        return (0, d["capacity"][s])

    model.x = pyo.Var(
        model.S,
        within=pyo.NonNegativeIntegers,
        bounds=x_bounds,
    )

    # Objective: minimize total cost
    def obj_rule(m):
        return sum(d["cost"][s] * m.x[s] for s in m.S)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint: total production must meet demand
    def demand_rule(m):
        return sum(m.x[s] for s in m.S) >= d["demand"]

    model.demand_con = pyo.Constraint(rule=demand_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "sources": ["coal", "gas", "nuclear"],
    "cost": {"coal": 4, "gas": 3, "nuclear": 2},
    "capacity": {"coal": 3000, "gas": 2000, "nuclear": 1500},
    "demand": 5000,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.SOURCES = pyo.Set(initialize=d["sources"])

    def cap_bounds(m, s):
        return (0, d["capacity"][s])

    model.production = pyo.Var(
        model.SOURCES,
        within=pyo.NonNegativeIntegers,
        bounds=cap_bounds,
    )

    def obj_rule(m):
        return sum(d["cost"][s] * m.production[s] for s in m.SOURCES)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.minimize)

    def demand_rule(m):
        return sum(m.production[s] for s in m.SOURCES) >= d["demand"]

    model.demand = pyo.Constraint(rule=demand_rule)

    return model


